#include <a6treeg.hpp>
#include <cmath>
#include <complex>
#include <cstdlib>
#include <iostream>
#include <FArray.hpp>
#include <heldefs_mod.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>
#include <W1jet.hpp>

// hep-ph/9708239, Eqs(8.4,8.8,8.14,9.2,9.7,10.1) Multiplied by (-i)
std::complex<double> a6treeg(int st, int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  using namespace heldefs_mod;
  using namespace sprods_com_mod;

  std::complex<double> res;

  if (st == hqpgmgpqbm) {
    res =
      ((za(j2,j4)*za(j4,j5)*zb(j1,j3)*zb(j1,j6))/
      (s(j2,j3)*s(j5,j6)*za(j3,j4)*zb(j1,j2))-
      (za(j4,j5)*std::pow(zb(j1,j3),2)*(-(za(j1,j2)*zb(j1,j6))+za(j2,j3)*zb(j3,j6)))/
      (s(j2,j3)*s(j5,j6)*zb(j1,j2)*t(j1,j2,j3))+
      (std::pow(za(j2,j4),2)*zb(j1,j6)*(-(za(j2,j5)*zb(j2,j3))+za(j4,j5)*zb(j3,j4)))/
      (s(j2,j3)*s(j5,j6)*za(j3,j4)*t(j2,j3,j4)));
  } else if (st == hqpgpgmqbm) {
    res =
      (-(((za(j3,j5)*zb(j2,j3)+za(j4,j5)*zb(j2,j4))*
      (-(za(j1,j3)*zb(j1,j6))-za(j2,j3)*zb(j2,j6)))/
      (s(j2,j3)*s(j5,j6)*za(j1,j2)*zb(j3,j4)))-
      (za(j1,j3)*za(j4,j5)*zb(j1,j2)*
      (-(za(j1,j3)*zb(j1,j6))-za(j2,j3)*zb(j2,j6)))/
      (s(j2,j3)*s(j5,j6)*za(j1,j2)*t(j1,j2,j3))+
      (za(j3,j4)*zb(j1,j6)*zb(j2,j4)*
      (za(j3,j5)*zb(j2,j3)+za(j4,j5)*zb(j2,j4)))/
      (s(j2,j3)*s(j5,j6)*zb(j3,j4)*t(j2,j3,j4)));
  } else if (st == hqpgpgpqbm) {
    // This amplitude corresponds to
    // q(4)+l(5) --> q_R(1)+l_R(6)+g_R(2)+g_R(3)
    res =
      (-std::pow(za(j4,j5),2))/(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j5,j6));
  } else if (st == hqpgpqbmgm) {
    res =
      (((za(j3,j5)*zb(j1,j3)+za(j4,j5)*zb(j1,j4))*
      (-(za(j1,j3)*zb(j1,j6))-za(j2,j3)*zb(j2,j6)))/
      (s(j5,j6)*za(j1,j2)*za(j2,j3)*zb(j1,j4)*zb(j3,j4))+
      (za(j3,j5)*zb(j1,j2)*(-(za(j1,j4)*zb(j1,j6))-za(j2,j4)*zb(j2,j6)))/
      (s(j5,j6)*za(j1,j2)*zb(j1,j4)*t(j1,j2,j4))-
      (za(j3,j4)*zb(j1,j6)*(za(j3,j5)*zb(j2,j3)+za(j4,j5)*zb(j2,j4)))/
      (s(j5,j6)*za(j2,j3)*zb(j3,j4)*t(j2,j3,j4)));
  } else if (st == hqpgpqbmgp) {
    res =
      (-za(j1,j3)*std::pow(za(j3,j5),2))/
      (za(j1,j2)*za(j1,j4)*za(j2,j3)*za(j3,j4)*za(j5,j6));
  } else if (st == hqpqbmgmgp) {
    res =
      (((-(za(j2,j5)*zb(j2,j4))-za(j3,j5)*zb(j3,j4))*
      (-(za(j1,j3)*zb(j1,j6))+za(j3,j4)*zb(j4,j6)))/
      (s(j3,j4)*s(j5,j6)*za(j1,j4)*zb(j2,j3))-
      (za(j1,j3)*za(j2,j5)*zb(j1,j4)*
      (-(za(j1,j3)*zb(j1,j6))+za(j3,j4)*zb(j4,j6)))/
      (s(j3,j4)*s(j5,j6)*za(j1,j4)*t(j1,j3,j4))-
      (za(j2,j3)*zb(j1,j6)*zb(j2,j4)*
      (-(za(j2,j5)*zb(j2,j4))-za(j3,j5)*zb(j3,j4)))/
      (s(j3,j4)*s(j5,j6)*zb(j2,j3)*t(j2,j3,j4)));
  } else if (st == hqpqbmgpgm) {
    res =
      -(-((za(j2,j4)*za(j2,j5)*zb(j1,j3)*zb(j1,j6))/
      (s(j3,j4)*s(j5,j6)*za(j2,j3)*zb(j1,j4)))+
      (za(j2,j5)*std::pow(zb(j1,j3),2)*(-(za(j1,j4)*zb(j1,j6))-za(j3,j4)*zb(j3,j6)))/
      (s(j3,j4)*s(j5,j6)*zb(j1,j4)*t(j1,j3,j4))+
      (std::pow(za(j2,j4),2)*zb(j1,j6)*(-(za(j2,j5)*zb(j2,j3))+za(j4,j5)*zb(j3,j4)))/
      (s(j3,j4)*s(j5,j6)*za(j2,j3)*t(j2,j3,j4)));
  } else if (st == hqpqbmgpgp) {
    res =
      (-std::pow(za(j2,j5),2))/(za(j1,j4)*za(j2,j3)*za(j3,j4)*za(j5,j6));
  } else {
    std::cout << "unimplemented st " << st << std::endl;
    std::exit(1);
  }

  res = res;  // @coverage-probe
  return res;
}

extern "C" {
  std::complex<double> a6treeg_wrapper(int st, int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* za_ptr, std::complex<double>* zb_ptr) {
    using namespace mxpart_mod;

    FArray2D<std::complex<double>> za(za_ptr, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(zb_ptr, mxpart, mxpart);

    return a6treeg(st, j1, j2, j3, j4, j5, j6, za, zb);
  }
}
